<script setup lang="ts">import type{Company}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const items=ref<Company[]>([]);const keyword=ref('');const editing=ref<Company|null>(null);async function load(){const term=keyword.value.trim();items.value=(await repository.admin.companies.list({...term?{keyword:term}:{},page:1,pageSize:100})).items}function edit(item:Company){editing.value=structuredClone(item)}function createCompany(){editing.value={id:crypto.randomUUID(),name:'',shortName:'',logoText:'企',industry:'',scale:'',ownership:'',cities:[],summary:'',description:'',websiteUrl:'https://',careersUrl:'https://',status:'active',featured:false}}async function save(){if(!editing.value)return;await repository.admin.companies.save(editing.value);editing.value=null;await load()}async function toggle(item:Company){await repository.admin.companies.updateStatus(item.id,item.status==='active'?'inactive':'active');await load()}onMounted(load)</script>
<template><section><header class="admin-page-head"><div><h1>公司管理</h1><p>维护企业档案、招聘官网和展示状态。</p></div><button class="cl-primary-button" @click="createCompany">新增公司</button></header><div class="admin-toolbar"><input v-model="keyword" aria-label="搜索公司" placeholder="搜索公司名称" @keyup.enter="load"/><button class="cl-quiet-button" @click="load">搜索</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>公司</th><th>行业</th><th>规模</th><th>城市</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.name}}</strong><br/><span class="admin-muted">{{item.ownership}}</span></td><td>{{item.industry}}</td><td>{{item.scale}}</td><td>{{item.cities.join('、')}}</td><td>{{item.status==='active'?'启用':'停用'}}</td><td><button class="admin-link-button" @click="edit(item)">编辑</button><button class="admin-link-button" @click="toggle(item)">{{item.status==='active'?'停用':'启用'}}</button></td></tr></tbody></table></div><div v-if="editing" class="form-layer" @mousedown.self="editing=null"><form class="drawer" @submit.prevent="save"><button class="close" type="button" @click="editing=null">×</button><h2>{{items.some(item=>item.id===editing?.id)?'编辑公司':'新增公司'}}</h2><label>公司名称<input v-model="editing.name" required/></label><label>所属行业<input v-model="editing.industry" required/></label><label>公司规模<input v-model="editing.scale"/></label><label>公司性质<input v-model="editing.ownership"/></label><label>招聘官网<input v-model="editing.careersUrl" type="url"/></label><label>简介<textarea v-model="editing.description" rows="5"></textarea></label><button class="cl-primary-button">保存公司</button></form></div></section></template>
<style scoped>.form-layer{position:fixed;z-index:60;inset:0;background:rgba(8,15,29,.45)}.drawer{position:absolute;top:0;right:0;width:min(100%,480px);height:100%;overflow:auto;padding:28px;background:var(--cl-surface)}.close{position:absolute;top:16px;right:16px;border:0;background:none;font-size:24px}.drawer label{display:grid;gap:5px;margin:14px 0;font-weight:700}.drawer input,.drawer textarea{padding:9px 10px;border:1px solid var(--cl-border);border-radius:7px;background:var(--cl-canvas)}.drawer>.cl-primary-button{width:100%;margin-top:12px}</style>
